package game

import (
	"sort"
	"sync"
)

// zone_layers.go — layers 4 and 5 for objects that are NOT on the
// battlefield (#3862, ADR 0039 amendment 2026-10-15).
//
//	CR 613.1d  "Layer 4: Type-changing effects are applied."
//	CR 613.1e  "Layer 5: Color-changing effects are applied."
//	CR 611.3a  "A continuous effect generated by a static ability isn't
//	            'locked in'; it applies at any given moment to whatever
//	            its text indicates."
//
// Three printed sentences reach past the battlefield:
//
//   - Mycosynth Lattice: "All cards that aren't on the battlefield,
//     spells, and permanents are colorless." Its ruling: "makes
//     everything, in every zone of the game, colorless."
//   - Maskwood Nexus: "The same is true for creature spells you control
//     and creature cards you own that aren't on the battlefield."
//   - Secret Arcade: "Nonland permanents you control and permanent
//     spells you control are enchantments in addition to their other
//     types."
//
// Until this file the layer pass computed a characteristic for a
// battlefield permanent and for nothing else, so a creature card in a
// hand was its printed self whatever a Nexus said, and a Cavern of Souls
// named for Elf would not pay for it.
//
// # The shape
//
// A battlefield static declares StaticAbility.AffectsZones: the zones
// whose objects its AppliesTo is asked of (ZoneStack for spells, and the
// hand, library, graveyard, exile and command zone for cards). The
// battlefield gather skips it. This step runs after layer 2 has settled
// who controls each spell, gathers every such static whose source has
// its abilities (CR 613.6's answer from the battlefield pass), and for
// each object in a declared zone applies the ones that accept it, layer
// 4 before layer 5 and by timestamp within a layer (CR 613.7). The
// result is a whole Characteristic stamped on Card.zoneLayered, and the
// type and colour readers (hasCardType, hasSubtype, HasSupertype,
// EffectiveColors, HasAllCreatureTypes and Effective) read it where they
// used to fall through to the printed card. That is the whole reader
// change: the cast payment's spend context, a tutor's filter, a
// "colorless spell" check and the wire all go through those six.
//
// While a static is applied, the object's stamp is the characteristic in
// progress, so a predicate that asks "is it a creature?" sees what the
// earlier effects in the step made it, exactly as the battlefield pass
// lets a later effect read an earlier one.
//
// # When it ends
//
// The stamp is re-derived on every pass, so it ends the pass after its
// source leaves the battlefield or loses its abilities, and a card that
// changes zone drops it at once (MoveCard; CR 400.7, a new object). A
// card moving between two zones off the battlefield while such a static
// is live bumps the layer version (layerVersionBump), and so does a
// cast, so the new object is stamped at the next read. A pass with no
// such static clears what an earlier pass stamped, once, and is
// otherwise one battlefield walk.
//
// # Not covered
//
// Dependency ordering (CR 613.8) among these effects. The battlefield's
// layer 4 orders a Nexus after an effect that makes something a
// creature; off the battlefield no catalogued effect makes a card a
// creature, so timestamp order is the whole answer. Cards outside the
// game (a sideboard, CR 400.11) are not in any zone of the game, and
// nothing applies to them.

// zoneLayerZones are the zones a static may declare in AffectsZones.
var zoneLayerZones = []ZoneKind{ZoneStack, ZoneHand, ZoneLibrary, ZoneGraveyard, ZoneExile, ZoneCommand}

// AffectsZoneUnsupported names the reason `zone` cannot be declared in
// StaticAbility.AffectsZones, or "" when it can. Used by
// effects.Register to refuse a declaration the step would ignore.
func AffectsZoneUnsupported(zone ZoneKind) string {
	for _, z := range zoneLayerZones {
		if z == zone {
			return ""
		}
	}
	if zone == ZoneBattlefield {
		return "a permanent is the battlefield pass's; declare the permanent half as a static of its own"
	}
	return "the zone layer step walks only " + joinZoneKinds(zoneLayerZones)
}

// zoneLayerIndex is the catalog-wide set of keys that declare a static
// over objects off the battlefield, so the step and the layer-version
// gate pay one map read per permanent rather than a catalog walk.
// Written at boot from effects.Register, read-only afterwards — the
// contract every Catalog* hook carries.
var zoneLayerIndex = struct {
	sync.RWMutex
	keys map[string]bool
}{keys: map[string]bool{}}

// IndexZoneLayers records that `key` declares a static with
// AffectsZones. Called once per card from effects.Register.
func IndexZoneLayers(key string, statics []StaticAbility) {
	if key == "" {
		return
	}
	for _, s := range statics {
		if len(s.AffectsZones) > 0 {
			zoneLayerIndex.Lock()
			zoneLayerIndex.keys[key] = true
			zoneLayerIndex.Unlock()
			return
		}
	}
}

func declaresZoneLayers(key string) bool {
	zoneLayerIndex.RLock()
	ok := zoneLayerIndex.keys[key]
	zoneLayerIndex.RUnlock()
	return ok
}

// zoneLayerSource is one battlefield static over objects off the
// battlefield, bound to the permanent it comes from.
type zoneLayerSource struct {
	eff   staticContinuousEffect
	layer Layer
	ts    int64
}

// covers reports whether the source's static reaches objects in `zone`.
func (s zoneLayerSource) covers(zone ZoneKind) bool {
	for _, z := range s.eff.ability.AffectsZones {
		if z == zone {
			return true
		}
	}
	return false
}

// zoneLayerSourcesLocked gathers the battlefield statics over objects
// off the battlefield, in layer and then timestamp order. Nil on a board
// with none, which is nearly every board. A source whose abilities the
// battlefield pass just removed contributes nothing.
//
// Caller must hold g.mu (write); the source pointers are into the
// battlefield slice and are good only for this pass.
func (g *Game) zoneLayerSourcesLocked() []zoneLayerSource {
	if g.Battlefield == nil || CatalogStaticAbilities == nil {
		return nil
	}
	var out []zoneLayerSource
	for i := range g.Battlefield.Cards {
		src := &g.Battlefield.Cards[i]
		if !declaresZoneLayers(catalogKeyOf(src)) || src.HasLostAllAbilities() {
			continue
		}
		for _, ab := range staticAbilitiesOf(src) {
			if len(ab.AffectsZones) == 0 || ab.AppliesTo == nil || ab.Apply == nil {
				continue
			}
			ts := staticTimestamp(src, ab, src.layerTimestamp())
			out = append(out, zoneLayerSource{
				eff:   staticContinuousEffect{ability: ab, source: src, timestamp: ts, live: true},
				layer: ab.Layer,
				ts:    ts,
			})
		}
	}
	sort.SliceStable(out, func(i, j int) bool {
		if out[i].layer != out[j].layer {
			return out[i].layer < out[j].layer
		}
		return out[i].ts < out[j].ts
	})
	return out
}

// zoneLayerPassLocked is the zone layer step. It re-derives
// Card.zoneLayered for every object off the battlefield while a static
// declares one, and clears what an earlier pass wrote when none does.
//
// Caller must hold g.mu (write).
func (g *Game) zoneLayerPassLocked() {
	sources := g.zoneLayerSourcesLocked()
	if len(sources) == 0 {
		if g.zoneLayersStamped {
			g.forEachObjectOffBattlefieldLocked(func(c *Card, _ ZoneKind) { c.zoneLayered = nil })
			g.zoneLayersStamped = false
		}
		return
	}
	g.zoneLayersStamped = true
	g.forEachObjectOffBattlefieldLocked(func(c *Card, zone ZoneKind) {
		g.stampZoneLayersLocked(c, zone, sources)
	})
}

// stampZoneLayersLocked applies the sources that reach `c` in `zone`.
func (g *Game) stampZoneLayersLocked(c *Card, zone ZoneKind, sources []zoneLayerSource) {
	c.zoneLayered = nil
	var ch *Characteristic
	for _, s := range sources {
		if !s.covers(zone) || !s.eff.ability.AppliesTo(c, g, s.eff.source) {
			continue
		}
		if ch == nil {
			base := zoneLayerBaseline(c)
			ch = &base
			// The characteristic in progress is what a later static's
			// AppliesTo reads (see the file comment).
			c.zoneLayered = ch
		}
		if s.layer == Layer4Type {
			applyTypeChange(s.eff, ch, c, g)
		} else {
			s.eff.Apply(ch, c, g)
		}
	}
}

// zoneLayerBaseline is the object's printed characteristic with the
// slices this step writes copied, so the printed cache it came from is
// never written (printed_cache.go's rule).
func zoneLayerBaseline(c *Card) Characteristic {
	ch := printedShared(c)
	ch.Supertypes = append([]string(nil), ch.Supertypes...)
	ch.Types = append([]string(nil), ch.Types...)
	ch.Subtypes = append([]string(nil), ch.Subtypes...)
	ch.Colors = append([]string(nil), ch.Colors...)
	return ch
}

// forEachObjectOffBattlefieldLocked walks every object the zone layer
// step reaches: each spell on the stack (not an ability), and every card
// in each seat's hand, library, graveyard and command zone and in exile.
//
// Caller must hold g.mu.
func (g *Game) forEachObjectOffBattlefieldLocked(fn func(c *Card, zone ZoneKind)) {
	if g.Stack != nil {
		for i := range g.Stack.Cards {
			c := &g.Stack.Cards[i]
			if item := g.StackMeta[c.InstanceID]; item == nil || item.Kind != StackItemSpell {
				continue
			}
			fn(c, ZoneStack)
		}
	}
	walk := func(z *Zone, kind ZoneKind) {
		if z == nil {
			return
		}
		for i := range z.Cards {
			fn(&z.Cards[i], kind)
		}
	}
	for _, p := range g.Seats {
		if p == nil {
			continue
		}
		walk(p.Hand, ZoneHand)
		walk(p.Library, ZoneLibrary)
		walk(p.Graveyard, ZoneGraveyard)
		walk(p.Command, ZoneCommand)
	}
	walk(g.Exile, ZoneExile)
}

// zoneLayerStaticIsLiveLocked reports whether any permanent on the
// battlefield has a static over objects off the battlefield: the gate
// on the layer-version bumps for a card changing zones off the
// battlefield and for a cast (layerVersionBump).
//
// Caller must hold g.mu.
func zoneLayerStaticIsLiveLocked(g *Game) bool {
	if g.Battlefield == nil {
		return false
	}
	for i := range g.Battlefield.Cards {
		if declaresZoneLayers(catalogKeyOf(&g.Battlefield.Cards[i])) {
			return true
		}
	}
	return false
}
